import logging

import pytest

from awx.main.models import (
    Job,
    JobTemplate,
    ProjectUpdate,
)

from awx.main.tests.live.tests.conftest import wait_for_job

logger = logging.getLogger(__name__)


class TestCancelDependencyChain:
    """Tests for cancel propagation through the dependency chain."""

    def test_fail_chain_includes_dependency_project_updates(self, admin, demo_inv, demo_proj):
        """Verify that Job.get_jobs_fail_chain() includes dependency
        project updates linked via dependent_jobs M2M."""
        jt, _ = JobTemplate.objects.get_or_create(
            name='test_fail_chain',
            defaults={
                'project': demo_proj,
                'playbook': 'helloworld.yml',
                'inventory': demo_inv,
            },
        )
        job = jt.create_unified_job()

        # A new job has no project_update FK set (only set by the runner)
        assert job.project_update_id is None
        assert job.get_jobs_fail_chain() == []

        # Simulate DependencyManager linking a project update via dependent_jobs M2M
        proj_update = demo_proj.project_updates.order_by('-created').first()
        if proj_update is None:
            pytest.skip('No project updates exist for demo project')

        job.dependent_jobs.add(proj_update)

        # The fail chain now includes dependent_jobs M2M entries
        chain = job.get_jobs_fail_chain()
        assert proj_update in chain

        # Clean up
        job.dependent_jobs.remove(proj_update)
        job.delete()

    def test_cancel_pending_job_cancels_dependency(self, admin, demo_inv, demo_proj):
        """When canceling a pending job that has a dependency project update,
        the cancel propagates to the dependency."""
        jt, _ = JobTemplate.objects.get_or_create(
            name='test_cancel_propagate',
            defaults={
                'project': demo_proj,
                'playbook': 'helloworld.yml',
                'inventory': demo_inv,
            },
        )
        job = jt.create_unified_job()

        # Set up the job as pending
        Job.objects.filter(pk=job.pk).update(status='pending', dependencies_processed=True)
        job.refresh_from_db()

        # Get a project update to use as dependency
        proj_update = demo_proj.project_updates.filter(status__in=('pending', 'waiting', 'running')).order_by('-created').first()

        if proj_update is None:
            pytest.skip('No active project updates exist for demo project')

        # Link via dependent_jobs M2M
        job.dependent_jobs.add(proj_update)

        # Cancel the job
        job.cancel()

        # Check that the dependency was canceled
        proj_update.refresh_from_db()
        logger.info(f'After job.cancel(): dep project_update status={proj_update.status}, cancel_flag={proj_update.cancel_flag}')

        assert proj_update.cancel_flag is True, f'Cancel did not propagate to dependency project update {proj_update.id}'

        # Clean up
        job.dependent_jobs.remove(proj_update)
        job.delete()
